use std::path::Path;
use serde::{Deserialize, Serialize};
use chrono::Utc;
use base64::Engine;

use ed25519_dalek::{VerifyingKey, Signature, Verifier};
use thiserror::Error;

/// The license format version (for forward compatibility).
pub const LICENSE_FORMAT: u32 = 1;

/// The built-in Ed25519 public key (SPKI DER, base64-encoded).
/// Generated by `openssl genpkey -algorithm ed25519` and extracted.
/// Replace with your actual production public key.

/// Public key as raw 32-byte compressed form (last 32 bytes of SPKI DER).
const PUBLIC_KEY_BYTES: &[u8] = include_bytes!("public_key.raw");

#[derive(Debug, Error)]
pub enum LicenseError {
    #[error("license file not found at {0}")]
    NotFound(String),
    #[error("failed to read license file: {0}")]
    Io(#[from] std::io::Error),
    #[error("invalid JSON: {0}")]
    Json(#[from] serde_json::Error),
    #[error("unsupported license format version {0}, expected {1}")]
    Version(u32, u32),
    #[error("missing required field: {0}")]
    MissingField(&'static str),
    #[error("invalid base64 signature")]
    BadSignatureEncoding,
    #[error("signature verification failed")]
    InvalidSignature,
    #[error("license expired at {0}")]
    Expired(String),
    #[error("artifact '{0}' not authorized by license")]
    ArtifactNotAuthorized(String),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct License {
    pub format: u32,
    pub feature: String,
    pub customer: String,
    pub issued_at: u64,
    pub expires_at: String,
    #[serde(default)]
    pub artifacts: Vec<String>,
    #[serde(skip_serializing, skip_deserializing)]
    pub signature: String,
}

/// The canonical payload that is signed: all fields except `signature`,
/// serialized as JSON with sorted keys and no whitespace.
#[derive(Debug, Clone, Serialize)]
struct SignedPayload {
    format: u32,
    feature: String,
    customer: String,
    issued_at: u64,
    expires_at: String,
    artifacts: Vec<String>,
}

impl License {
    /// Load and verify a license file from the given path.
    pub fn load(path: &Path) -> Result<Self, LicenseError> {
        let content = std::fs::read_to_string(path)?;
        let license: Self = serde_json::from_str(&content)?;
        license.verify()?;
        Ok(license)
    }

    /// Verify the signature and check expiry.
    fn verify(&self) -> Result<(), LicenseError> {
        if self.format != LICENSE_FORMAT {
            return Err(LicenseError::Version(self.format, LICENSE_FORMAT));
        }
        if self.feature != "judge" {
            return Err(LicenseError::MissingField("feature"));
        }
        if self.signature.is_empty() {
            return Err(LicenseError::MissingField("signature"));
        }

        // Reconstruct the signed payload
        let payload = SignedPayload {
            format: self.format,
            feature: self.feature.clone(),
            customer: self.customer.clone(),
            issued_at: self.issued_at,
            expires_at: self.expires_at.to_string(),
            artifacts: self.artifacts.clone(),
        };
        let canonical = serde_json::to_vec(&payload)?;

        // Verify Ed25519 signature
        let sig_bytes = base64::engine::general_purpose::STANDARD
            .decode(&self.signature)
            .map_err(|_| LicenseError::BadSignatureEncoding)?;
        let signature = Signature::try_from(sig_bytes.as_slice())
            .map_err(|_| LicenseError::BadSignatureEncoding)?;

        let vk = VerifyingKey::try_from(PUBLIC_KEY_BYTES)
            .map_err(|_| LicenseError::InvalidSignature)?;
        vk.verify(&canonical, &signature)
            .map_err(|_| LicenseError::InvalidSignature)?;

        // Check expiry
        let _now = Utc::now();
        if Utc::now().to_rfc3339() > self.expires_at {
            return Err(LicenseError::Expired(self.expires_at.clone()));
        }
        Ok(())
    }

    /// Check if the given artifact ID (file stem) is authorized.
    /// Empty `artifacts` list or `["*"]` means all artifacts allowed.
    pub fn authorizes_artifact(&self, artifact_id: &str) -> bool {
        self.artifacts.is_empty() || self.artifacts.iter().any(|a| a == "*" || a == artifact_id)
    }

    /// Whether the license is currently valid (not expired).
    pub fn is_valid(&self) -> bool {
        Utc::now().to_rfc3339() <= self.expires_at
    }
}

/// Load the judge license from the standard config directory.
/// Returns `None` if no license file exists or if it fails to load/verify.
pub fn load_judge_license() -> Option<License> {
    let path = license_path()?;
    License::load(&path).ok()
}

/// Standard location for the license file: `~/.config/triqui/license.json`
fn license_path() -> Option<std::path::PathBuf> {
    dirs::config_dir().map(|d| d.join("triqui").join("license.json"))
}

/// Human-readable status for the UI.
#[derive(Debug, Clone, Serialize)]
#[derive(specta::Type)]
pub enum LicenseStatus {
    Licensed { customer: String, expires_at: String, artifacts: Vec<String> },
    Invalid { reason: String },
    NotFound,
}

impl License {
    pub fn status(&self) -> LicenseStatus {
        LicenseStatus::Licensed {
            customer: self.customer.clone(),
            expires_at: self.expires_at.to_string(),
            artifacts: self.artifacts.clone(),
        }
    }
}
